function seedProblems(db: any, problems: Problem[]): number {
  const insert = db.prepare(`
    INSERT OR IGNORE INTO problems
      (id, concept_id, difficulty, type, stem,
       answer_json, solution_steps_json, misconceptions_json, is_generated)
    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)
  `)
  const insertAll = db.transaction(() => {
    let inserted = 0
    for (const p of problems) {
      const result = insert.run(
        p.id, p.conceptId, p.difficulty, p.type, p.stem,
        JSON.stringify(p.answer),
        JSON.stringify(p.solutionSteps),
        JSON.stringify(p.commonMisconceptions),
        p.isGenerated
      )
      inserted += result.changes
    }
    return inserted
  })
  return insertAll()
}

const db = new Database(path.resolve(DB_PATH))
console.log(`[enrich] Opening database: ${DB_PATH}`)
console.log(`[enrich] Problems to insert: ${PROBLEMS.length}`)
const inserted = seedProblems(db, PROBLEMS)
console.log(`[enrich] Inserted: ${inserted} new problems`)
console.log(`[enrich] Skipped (duplicates): ${PROBLEMS.length - inserted}`)
const summary = db.prepare('SELECT concept_id, difficulty, COUNT(*) as count FROM problems GROUP BY concept_id, difficulty ORDER BY concept_id, difficulty').all() as {concept_id:string, difficulty:string, count:number}[]
console.log('\n[enrich] Updated problem counts:')
let lastConcept = ''
for (const row of summary) {
  if (row.concept_id !== lastConcept) { lastConcept = row.concept_id; process.stdout.write(`\n  ${row.concept_id}: `) }
  process.stdout.write(`${row.difficulty}(${row.count}) `)
}
const total = db.prepare('SELECT COUNT(*) as c FROM problems').get() as {c:number}
console.log(`\n\n[enrich] Total problems in database: ${total.c}`)
db.close()
